use super::Model;
use crate::ecs::World;
use alloc::borrow::Cow;

/// Root key metadata generated by `#[model(persistence)]`, independent of storage features.
#[doc(hidden)]
pub trait PersistModel: Model {
    const KEY: Option<&'static str>;
}

/// Compile-time registration selected by the Model declaration.
#[doc(hidden)]
pub trait ModelRegistration<M: Model>: PersistenceState {
    fn register(world: &mut World, value: M, key: Option<Cow<'static, str>>) -> M::Handle;
}

impl<M: Model<Persistence = ()>> ModelRegistration<M> for () {
    fn register(world: &mut World, value: M, _: Option<Cow<'static, str>>) -> M::Handle {
        install(world, value)
    }
}

pub(crate) fn install<M: Model>(world: &mut World, value: M) -> M::Handle {
    let (registration, handle) = super::register(world, value);
    let entity = world.spawn_empty();
    world.insert(entity, registration);
    handle
}

#[cfg(feature = "persistence")]
impl<M> ModelRegistration<M> for Candidate
where
    M: PersistModel
        + crate::core::persistence::value::PersistValue
        + Model<Persistence = Candidate>,
{
    fn register(world: &mut World, value: M, key: Option<Cow<'static, str>>) -> M::Handle {
        use crate::core::persistence::PersistenceRegistry;
        let key = key.or_else(|| M::KEY.map(Cow::Borrowed));
        let Some(key) = key else {
            return install(world, value);
        };
        if world.resource::<PersistenceRegistry>().is_none() {
            return install(world, value);
        }
        world
            .with_resource_box::<PersistenceRegistry, _>(move |registry, world| {
                registry.register_model(world, value, key)
            })
            .expect("persistence registry is installed")
    }
}

/// Per-root persistence state selected by generated Model declarations.
#[doc(hidden)]
pub trait PersistenceState: sealed::Sealed + Default + 'static {
    fn changed(&self);

    #[cfg(feature = "persistence")]
    fn registration_error(&self) -> Option<crate::core::persistence::PersistenceError> {
        None
    }
}

#[cfg(feature = "persistence")]
mod endpoint;
#[cfg(feature = "persistence")]
pub(crate) use endpoint::PersistenceEndpoint;

mod sealed {
    pub trait Sealed {}
    impl Sealed for () {}
}

impl PersistenceState for () {
    fn changed(&self) {}
}

#[cfg(feature = "persistence")]
mod candidate {
    use core::cell::Cell;

    use super::PersistenceState;

    /// A conservative save candidate, independent of observation and effect delivery.
    #[doc(hidden)]
    pub struct Candidate {
        revision: Cell<u64>,
        pending: Cell<bool>,
        registration_error: Cell<Option<crate::core::persistence::PersistenceError>>,
    }

    impl super::sealed::Sealed for Candidate {}

    impl Default for Candidate {
        fn default() -> Self {
            Self {
                revision: Cell::new(0),
                pending: Cell::new(true),
                registration_error: Cell::new(None),
            }
        }
    }

    impl PersistenceState for Candidate {
        fn changed(&self) {
            self.revision.set(self.revision.get().saturating_add(1));
            self.pending.set(true);
        }
        fn registration_error(&self) -> Option<crate::core::persistence::PersistenceError> {
            self.registration_error.get()
        }
    }

    impl Candidate {
        pub(crate) fn reject_registration(
            &self,
            error: crate::core::persistence::PersistenceError,
        ) {
            self.registration_error.set(Some(error));
        }
        pub fn pending(&self) -> bool {
            self.pending.get()
        }

        pub fn stamp(&self) -> u64 {
            self.revision.get()
        }

        /// Confirm only the saved snapshot, never a subsequent mutation.
        pub fn confirm(&self, stamp: u64) {
            if stamp != u64::MAX && self.revision.get() == stamp {
                self.pending.set(false);
            }
        }
    }

    const _: () = assert!(core::mem::size_of::<Candidate>() <= 16);

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn stale_confirmation_and_saturated_revisions_remain_pending() {
            let state = Candidate::default();
            assert!(state.pending());
            state.confirm(state.stamp());
            assert!(!state.pending());
            let old = state.stamp();
            state.changed();
            state.confirm(old);
            assert!(state.pending());
            state.confirm(state.stamp());
            assert!(!state.pending());
            state.revision.set(u64::MAX - 1);
            state.changed();
            state.confirm(u64::MAX);
            state.changed();
            assert_eq!(state.stamp(), u64::MAX);
            assert!(state.pending());
        }
    }
}

#[cfg(feature = "persistence")]
pub use candidate::Candidate;

#[cfg(all(test, feature = "std", feature = "persistence"))]
mod tests;
